<script setup lang="ts">
import {computed,ref} from 'vue';
import {Check,Clock,LoaderCircle,TriangleAlert,ArrowRight,Search} from 'lucide-vue-next';
import {useDesktop} from '../useDesktop';
const d=useDesktop();const {state}=d;const filter=ref('all');
const tasks=computed(()=>[...state.value.tasks].filter(t=>filter.value==='all'||t.status===filter.value&&(filter.value!=='failed'||!d.preferences.value.dismissedTasks.includes(t.id))).reverse());
const labels:Record<string,string>={install:'准备酒馆',start:'启动服务',stop:'停止服务',update:'更新本体',switch:'切换版本'};
</script>
<template><main class="global-workspace"><div class="page-intro"><span class="eyebrow">ACTIVITY</span><h1>任务中心</h1><p>准备环境、启动和更新的进度，都在这里。</p></div><p v-if="state.task_history_error" class="warning" role="alert">{{state.task_history_error}}</p><p class="help-text">本机会保留最近 100 项任务及简要日志。已取消的准备可以重新开始，进入版本与数据切换后不能取消。</p><div class="filter-tabs"><button v-for="item in [['all','全部'],['running','进行中'],['failed','需要处理'],['success','已完成'],['cancelled','已取消']]" :key="item[0]" :class="{active:filter===item[0]}" @click="filter=item[0]">{{item[1]}}</button></div><section v-if="!tasks.length" class="empty"><Clock :size="30"/><h3>这里暂时没有任务</h3><p>创建或启动酒馆后，任务会保留在这里供你查看。</p></section><article v-for="task in tasks" :key="task.id" :class="['panel activity-card',task.status]"><div class="activity-icon"><LoaderCircle v-if="task.status==='running'" class="spin" :size="22"/><TriangleAlert v-else-if="task.status==='failed'" :size="22"/><Check v-else :size="22"/></div><div class="activity-content"><div class="panel-title"><h3>{{labels[task.kind]||'实例任务'}} <small>{{state.instances.find(i=>i.id===task.instance_id)?.name||'酒馆实例'}}</small></h3><span class="badge">{{task.status==='running'?'进行中':task.status==='failed'?(d.preferences.value.dismissedTasks.includes(task.id)?'已标记处理':'需要处理'):task.status==='cancelled'?'已取消':'已完成'}}</span></div><p>{{task.stage}}</p><progress v-if="task.status==='running'" :value="task.percent" max="100"/><p v-if="task.error" class="warning" role="alert">{{task.error}}</p><p v-if="task.error_code" class="help-text">{{task.error_code==='interrupted'?'上次运行中断，请先检查实例恢复状态':task.error_code==='timeout'?'任务超时，可检查网络后重新开始':task.error_code==='cancelled'?'准备已取消，原数据保留':'操作未完成，请查看错误与日志'}}</p><div class="row"><button v-if="task.cancellable" class="secondary" :disabled="d.busyIds.value.has(task.instance_id)" @click="d.act('cancelTask',{taskId:task.id,instanceId:task.instance_id})">取消准备</button><button v-if="task.retryable" class="secondary" :disabled="state.instances.find(i=>i.id===task.instance_id)?.status==='busy'||d.busyIds.value.has(task.instance_id)" @click="d.act('retryTask',{taskId:task.id,instanceId:task.instance_id})">重新开始</button><button v-if="task.status==='failed'&&!d.preferences.value.dismissedTasks.includes(task.id)" class="text-button" @click="d.dismissTask(task.id)">标记已处理</button><button class="text-button" @click="d.inspectTask(task.instance_id)">查看实例与处理入口 <ArrowRight :size="15"/></button></div><details v-if="task.logs?.length"><summary>查看任务日志</summary><pre class="log-console">{{task.logs.join('\n')}}</pre></details></div></article></main></template>
